from ielts_h import rstory
READ = [rstory('My New Room', 'Kosakata tema', "Dina has a new bedroom. It is on the second floor. There is a wardrobe next to the door and a desk near the window. On the desk there is a lamp and a small mirror. Under the bed there is a soft carpet. Dina's mother helps her clean the room with a broom every Sunday.",
 'Dina punya kamar tidur baru. Letaknya di lantai dua. Ada lemari pakaian di sebelah pintu dan meja belajar di dekat jendela. Di atas meja ada lampu dan sebuah cermin kecil. Di bawah tempat tidur ada karpet yang lembut. Ibu Dina membantunya membersihkan kamar dengan sapu setiap hari Minggu.',
 [('Where is the wardrobe?', 'Next to the door', 'Near the window', 'Under the bed', 'On the desk', 'A wardrobe next to the door.'), ('What is on the desk?', 'A lamp and a small mirror', 'A broom and a carpet', 'A towel and a fan', 'A sofa and a shelf', 'Lamp and mirror.'), ('What do they use to clean the room?', 'A broom', 'A bucket only', 'A washing machine', 'A towel', 'With a broom.')], [], [('Lemari ada di sebelah pintu.', 'The wardrobe is next to the ___.', 'door', 'Next to the door.'), ('Ada karpet di bawah tempat tidur.', 'There is a soft ___ under the bed.', 'carpet', 'A soft carpet.')])]
